const pptxgen = require("pptxgenjs");

// ── SHARED PALETTE ──────────────────────────────────────────────
const BG       = "0A0F2E";   // dark navy
const CARD     = "161E3A";   // card navy
const GOLD     = "C9A84C";   // gold accent
const BLUE     = "2E75B6";   // blue accent
const WHITE    = "FFFFFF";
const MUTED    = "8899AA";

// ── CHART 1: REVENUE PROJECTIONS (Slide 8) ──────────────────────
// Target area: x=0.35 y=1.15 w=5.8 h=3.8  (full slide 10×5.625)
// We output a standalone 5.8×3.8 slide so it pastes at exact size
{
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  // Custom slide size matching the chart hole exactly
  pres.defineLayout({ name: "CHART8", width: 5.8, height: 3.8 });
  pres.layout = "CHART8";

  const slide = pres.addSlide();
  slide.background = { color: BG };

  // Grouped vertical bar chart — Year 1/3/7 users + Year 7 revenue
  slide.addChart(pres.charts.BAR, [
    {
      name: "Users (thousands)",
      labels: ["Year 1\n50K users", "Year 3\n2M users", "Year 7\n15M users"],
      values: [50, 2000, 15000],
    }
  ], {
    x: 0.15, y: 0.1, w: 3.3, h: 3.55,
    barDir: "col",
    chartColors: [BLUE, BLUE, GOLD],
    chartArea: { fill: { color: CARD }, border: { color: BLUE, pt: 1 } },
    plotArea: { fill: { color: CARD } },
    catAxisLabelColor: MUTED,
    catAxisLabelFontSize: 9,
    valAxisLabelColor: MUTED,
    valAxisLabelFontSize: 8,
    valGridLine: { color: "1E2A4A", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelColor: WHITE,
    dataLabelFontSize: 10,
    dataLabelPosition: "outEnd",
    showLegend: false,
    valAxisMinVal: 0,
  });

  // Revenue callout card (right side)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 3.65, y: 0.1, w: 2.0, h: 3.55,
    fill: { color: CARD },
    line: { color: GOLD, width: 1 },
  });

  slide.addText("$18B", {
    x: 3.65, y: 0.7, w: 2.0, h: 1.0,
    fontSize: 36, bold: true, color: GOLD,
    align: "center", valign: "middle", margin: 0,
  });
  slide.addText("Year 7 Revenue", {
    x: 3.65, y: 1.65, w: 2.0, h: 0.35,
    fontSize: 11, color: WHITE,
    align: "center", valign: "middle", margin: 0,
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 4.05, y: 2.1, w: 1.2, h: 0.02,
    fill: { color: GOLD }, line: { color: GOLD, width: 0 },
  });
  slide.addText("★ Growth path: organic community\n→ enterprise sales motion\n→ IBM Quantum + Starling (Y3)", {
    x: 3.7, y: 2.25, w: 1.9, h: 1.2,
    fontSize: 8, color: MUTED, italic: true,
    align: "center", valign: "top", margin: 0,
  });

  await pres.writeFile({ fileName: "/mnt/user-data/outputs/CHART_Slide8_Revenue.pptx" });
  console.log("Chart 1 written.");
}

// ── CHART 2: USE OF FUNDS (Slide 11) ────────────────────────────
// Target area: x=0.3 y=1.2 w=4.5 h=3.8
{
  const pres = new pptxgen();
  pres.defineLayout({ name: "CHART11", width: 4.5, height: 3.8 });
  pres.layout = "CHART11";

  const slide = pres.addSlide();
  slide.background = { color: BG };

  // Doughnut chart
  slide.addChart(pres.charts.DOUGHNUT, [
    {
      name: "Allocation",
      labels: ["Infrastructure 38%", "Staff Runway 28%", "Platform Dev 12%", "Legal & IP 15%", "Reserve 7%"],
      values: [38, 28, 12, 15, 7],
    }
  ], {
    x: 0.1, y: 0.1, w: 2.6, h: 3.55,
    chartColors: [GOLD, BLUE, "4A90D9", "7FB3E8", MUTED],
    chartArea: { fill: { color: CARD }, border: { color: GOLD, pt: 1 } },
    plotArea: { fill: { color: CARD } },
    showPercent: false,
    showValue: false,
    showLabel: false,
    showLegend: true,
    legendPos: "b",
    legendColor: MUTED,
    legendFontSize: 7,
    holeSize: 55,
  });

  // Breakdown list on right
  const items = [
    { label: "Infrastructure",   amt: "$665,000",  pct: "38%", color: GOLD },
    { label: "Staff Runway",     amt: "$490,000",  pct: "28%", color: BLUE },
    { label: "Platform Dev",     amt: "$210,000",  pct: "12%", color: "4A90D9" },
    { label: "Legal & IP",       amt: "$262,500",  pct: "15%", color: "7FB3E8" },
    { label: "Reserve",          amt: "$122,500",  pct: "7%",  color: MUTED },
  ];

  items.forEach((item, i) => {
    const yBase = 0.25 + i * 0.65;
    // Color bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 2.85, y: yBase, w: 0.06, h: 0.45,
      fill: { color: item.color }, line: { color: item.color, width: 0 },
    });
    slide.addText(item.label, {
      x: 3.0, y: yBase, w: 1.35, h: 0.25,
      fontSize: 9, bold: true, color: WHITE,
      align: "left", valign: "top", margin: 0,
    });
    slide.addText(`${item.amt}  ·  ${item.pct}`, {
      x: 3.0, y: yBase + 0.24, w: 1.35, h: 0.2,
      fontSize: 8, color: MUTED,
      align: "left", valign: "top", margin: 0,
    });
  });

  await pres.writeFile({ fileName: "/mnt/user-data/outputs/CHART_Slide11_UseFunds.pptx" });
  console.log("Chart 2 written.");
}

console.log("All done.");

