slide.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.08,
  fill: { color: GOLD }, line: { color: GOLD, width: 0 },
});

// ── BOTTOM GOLD BAR ───────────────────────────────────────────────
slide.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 5.545, w: 10, h: 0.08,
  fill: { color: GOLD }, line: { color: GOLD, width: 0 },
});

// ── SECTION LABEL ─────────────────────────────────────────────────
slide.addText("THE COGNITIVE ARCHITECTURE", {
  x: 0.5, y: 0.18, w: 9, h: 0.35,
  fontSize: 12, bold: true, color: GOLD,
  charSpacing: 4, align: "left", valign: "middle", margin: 0,
});

// ── HEADLINE ──────────────────────────────────────────────────────
slide.addText("Two Models. One Mind. Zero Confabulation.", {
  x: 0.5, y: 0.58, w: 9, h: 0.5,
  fontSize: 24, bold: true, color: WHITE,
  align: "left", valign: "middle", margin: 0,
});

// ── FOOTER ────────────────────────────────────────────────────────
slide.addText("HQC.AI  |  Confidential  2026", {
  x: 0.3, y: 5.28, w: 9.4, h: 0.22,
  fontSize: 9, color: MUTED, align: "right", valign: "middle", margin: 0,
});

// ── FOOTNOTE ──────────────────────────────────────────────────────
slide.addText("The subconscious never speaks to the user. The main model never operates without it. Neither knows the other's reasoning.", {
  x: 0.35, y: 5.02, w: 9.3, h: 0.22,
  fontSize: 9, italic: true, color: MUTED, align: "left", valign: "middle", margin: 0,
});

// ════════════════════════════════════════════════════════════════
// LEFT PANEL — SUBCONSCIOUS MODEL
// ════════════════════════════════════════════════════════════════
const LP = { x: 0.35, y: 1.22, w: 4.2, h: 3.65 };

// Panel background
slide.addShape(pres.shapes.RECTANGLE, {
  x: LP.x, y: LP.y, w: LP.w, h: LP.h,
  fill: { color: CARD }, line: { color: BLUE, width: 1 },
});
// Blue left accent bar
slide.addShape(pres.shapes.RECTANGLE, {
  x: LP.x, y: LP.y, w: 0.07, h: LP.h,
  fill: { color: BLUE }, line: { color: BLUE, width: 0 },
});

// Panel header
slide.addShape(pres.shapes.RECTANGLE, {
  x: LP.x, y: LP.y, w: LP.w, h: 0.52,
  fill: { color: "1A2748" }, line: { color: BLUE, width: 0 },
});
slide.addText("SUBCONSCIOUS MODEL", {
  x: LP.x + 0.12, y: LP.y + 0.02, w: LP.w - 0.15, h: 0.26,
  fontSize: 11, bold: true, color: BLUE, charSpacing: 2,
  align: "left", valign: "middle", margin: 0,
});
slide.addText("Stateless · Boots on demand · No persona · No user contact", {
  x: LP.x + 0.12, y: LP.y + 0.27, w: LP.w - 0.15, h: 0.22,
  fontSize: 8, italic: true, color: MUTED,
  align: "left", valign: "middle", margin: 0,
});

// Role description
slide.addText("Sees itself as part of Hanna / Harry — not a separate entity. Handles memory maintenance and pre-checks all output before the main model ever sees it.", {
  x: LP.x + 0.15, y: LP.y + 0.6, w: LP.w - 0.25, h: 0.55,
  fontSize: 9, color: WHITE,
  align: "left", valign: "top", margin: 0,
});

// ── THREE CONFABULATION CHECK LAYERS ──────────────────────────────
const checks = [
  {
    label: "Vector Self-Check",
    body: "Verifies incoming memory against the user's own established ground truth before the main model sees it.",
    color: BLUE,
  },
  {
    label: "Knowledge Anchor Check",
    body: "Checks against documented facts and science. No investment in preferred conclusions.",
    color: BLUE,
  },
  {
    label: "Extrapolation Audit",
    body: "Flags both over- and under-extrapolation. Confidence matched to actual evidence in both directions.",
    color: BLUE,
  },
];

checks.forEach((c, i) => {
  const cy = LP.y + 1.25 + i * 0.77;
  // Row background
  slide.addShape(pres.shapes.RECTANGLE, {
    x: LP.x + 0.1, y: cy, w: LP.w - 0.15, h: 0.68,
