    x: LP.x + 0.25, y: cy + 0.04, w: LP.w - 0.4, h: 0.22,
    fontSize: 10, bold: true, color: GOLDL,
    align: "left", valign: "top", margin: 0,
  });
  slide.addText(c.body, {
    x: LP.x + 0.25, y: cy + 0.26, w: LP.w - 0.4, h: 0.38,
    fontSize: 8.5, color: WHITE,
    align: "left", valign: "top", margin: 0,
  });
});

